#include<bits/stdc++.h>

using namespace std;

int main(){
  int N,L,R;
  cin >> N >> L >> R;
  vector<int> res;

  for(int i=1;i<=L-1;i++){res.push_back(i);}
  for(int i=R;i>=L;i--){res.push_back(i);}
  for(int i=R+1;i<=N;i++){res.push_back(i);}

  for(int i=0;i<N;i++){
    if(i){cout << " ";}
    cout << res[i];
  }cout << "\n";
  return 0;
}
